<template>
  <div class="s-page"><div class="s-page-heading"><div><p class="s-eyebrow">01 / DISCOVER</p><h1>你的数据，藏着哪些模式？</h1><p>从代表曲线、样本分布与模式差异，理解每一段时间序列。</p></div><span class="s-engine-label"><span class="s-dot"></span> 鼠先知引擎</span></div>
    <div v-if="!studio.selected" class="s-panel s-empty"><el-icon><Aim /></el-icon><h3>先选择一份数据</h3><p>内置能源与工业场景示例，也支持上传你自己的 CSV。</p><RouterLink to="/datasets" class="s-button primary">前往数据集 →</RouterLink></div>
    <template v-else><form class="s-panel s-control-bar" @submit.prevent="run"><label class="s-field s-grow">数据集<select :value="studio.selectedId" @change="studio.select($event.target.value)"><option v-for="d in studio.datasets" :key="d.id" :value="d.id">{{ d.name }}</option></select></label><label class="s-field">窗口长度<input v-model.number="windowSize" type="number" min="8" max="256" required /></label><label class="s-field">窗口步长<input v-model.number="stride" type="number" min="1" :max="windowSize" required /></label><label class="s-field">随机种子<input v-model.number="seed" type="number" min="0" max="2147483647" required /></label><button class="s-button primary" :disabled="busy || running" type="submit"><el-icon><Aim /></el-icon>{{ running ? '正在探索…' : '发现数据结构' }}</button><div class="s-variable-row"><span>分析变量</span><label v-for="column in studio.selected.columns" :key="column"><input v-model="columns" type="checkbox" :value="column" />{{ column }}</label></div></form>
    <JobStatus :job="studio.discovery" />
    <div v-if="!result && !running" class="s-panel s-empty"><el-icon><DataAnalysis /></el-icon><h3>让模式自己浮现</h3><p>选择分析变量与窗口长度，鼠先知引擎将建立结构探索实验。</p><small>数据按时间划分，末尾 20% 预留给后续独立评估。</small></div>
    <template v-if="result"><div class="s-result-banner"><span><el-icon><CircleCheck /></el-icon>结构实验已完成 · {{ studio.discovery.id.slice(0, 8) }}</span><label>查看历史实验<select :value="studio.discovery.id" @change="studio.discoveryId = $event.target.value"><option v-for="j in studio.discoveries.filter(j => j.status === 'completed')" :key="j.id" :value="j.id">{{ date(j.created) }} · {{ j.id.slice(0, 8) }}</option></select></label></div><section class="s-stats-row"><div><span>发现模式</span><strong>{{ result.clusters.length.toString().padStart(2, '0') }}</strong><small>由数据结构探索得到</small></div><div><span>训练窗口</span><strong>{{ result.train_windows }}</strong><small>用于结构发现与生成</small></div><div><span>独立留出窗口</span><strong>{{ result.holdout_windows }}</strong><small>仅用于后续质量评估</small></div><div><span>低覆盖模式</span><strong>{{ result.clusters.filter(c => c.underrepresented).length }}</strong><small>占比低于 15%，建议审查</small></div></section>
    <div class="s-two-col"><section class="s-panel"><div class="s-section-heading"><h2>模式分布</h2><span>二维结构投影</span></div><StudioChart :option="scatter" :height="310" /><p class="s-chart-note">每个点代表一个训练窗口；二维投影用于探索，不代表真实类别标签。</p></section><section class="s-panel"><div class="s-section-heading"><h2>数据覆盖</h2><span>{{ result.train_windows }} 个窗口</span></div><div v-for="cluster in result.clusters" :key="cluster.id" class="s-coverage-row"><div><span><i :style="{ background: colors[cluster.id] }"></i>{{ cluster.name }}</span><strong>{{ percent(cluster.share) }} <small>{{ cluster.count }} 个</small></strong></div><div class="s-progress-track"><span :style="{ width: percent(cluster.share), background: colors[cluster.id] }"></span></div><small v-if="cluster.underrepresented" class="s-amber">样本较少 · 可进一步检查覆盖需求</small></div><p class="s-chart-note">低占比不等于异常；是否需要补充，由具体下游任务决定。</p></section></div>
    <div class="s-section-heading"><h2>模式原型与代表曲线</h2><label class="s-inline-field">查看变量<select v-model.number="channel"><option v-for="(name, i) in studio.discovery.config.columns" :key="name" :value="i">{{ name }}</option></select></label></div><section class="s-prototype-grid"><article v-for="cluster in result.clusters" :key="cluster.id" class="s-panel s-prototype"><div class="s-section-heading"><h3><i class="s-color-dot" :style="{ background: colors[cluster.id] }"></i>{{ cluster.name }}</h3><span :class="['s-status', cluster.underrepresented ? 'planned' : 'completed']">{{ cluster.underrepresented ? '低覆盖' : '已识别' }}</span></div><StudioChart :option="prototype(cluster)" :height="170" /><div class="s-prototype-bottom"><span>{{ cluster.count }} 个窗口 · {{ percent(cluster.share) }}</span><RouterLink :to="{ path: '/generate', query: { target: cluster.id } }" class="s-text-link">扩充此模式 ↗</RouterLink></div></article></section><div class="s-bottom-callout"><div><strong>理解结构之后，创造新的可能。</strong><p>选择目标模式，构建候选数据，并验证它对下游任务是否有用。</p></div><RouterLink to="/generate" class="s-button primary">进入数据生成 →</RouterLink></div></template></template>
  </div>
</template>
<script setup>
import { computed, ref, watch } from 'vue'
import { Aim, DataAnalysis, CircleCheck } from '@element-plus/icons-vue'
import { useStudioStore } from '../../stores/studio'
import StudioChart from '../../components/studio/StudioChart.vue'
import JobStatus from '../../components/studio/JobStatus.vue'
import { base, colors, lines, percent, date } from '../../components/studio/chartOptions'
const studio = useStudioStore(), windowSize = ref(48), stride = ref(48), seed = ref(42), columns = ref([]), channel = ref(0), busy = ref(false)
watch(() => studio.selected?.id, () => { columns.value = [...(studio.selected?.columns || [])]; channel.value = 0; const suggested = Math.max(8, Math.min(48, Math.floor((studio.selected?.rows || 480) / 10))); windowSize.value = suggested; stride.value = suggested }, { immediate: true })
watch(() => studio.discovery?.id, () => { channel.value = 0 })
const running = computed(() => ['queued', 'running'].includes(studio.discovery?.status))
const result = computed(() => studio.discovery?.status === 'completed' ? studio.discovery.result : null)
const scatter = computed(() => ({ ...base, grid: { left: 44, right: 16, top: 40, bottom: 38, containLabel: true }, tooltip: { ...base.tooltip, trigger: 'item' }, xAxis: { ...base.xAxis, type: 'value', name: '结构维度 1', nameLocation: 'middle', nameGap: 28 }, yAxis: { ...base.yAxis, name: '结构维度 2', nameLocation: 'middle', nameGap: 32 }, series: (result.value?.clusters || []).map(c => ({ name: c.name, type: 'scatter', symbolSize: 10, itemStyle: { opacity: 0.8, borderColor: '#ffffff', borderWidth: 1 }, data: result.value.points.filter(p => p.cluster === c.id).map(p => [p.x, p.y]) })) }))
function prototype(c) { return { ...lines([{ name: '代表窗口', data: c.representative.map(p => p[channel.value]), lineStyle: { width: 1, type: 'dashed' }, itemStyle: { color: '#bdc9c1' } }, { name: '模式均值', data: c.mean_curve.map(p => p[channel.value]), itemStyle: { color: colors[c.id] } }]), grid: { left: 6, right: 6, top: 28, bottom: 4, containLabel: true } } }
async function run() { if (!columns.value.length) { studio.error = '请至少选择一个数值变量'; return } busy.value = true; try { await studio.submit('discover', { dataset_id: studio.selectedId, window: windowSize.value, stride: stride.value, seed: seed.value, columns: columns.value }) } catch { /* banner */ } finally { busy.value = false } }
</script>
